INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63659615', 63659615, 'analyze_legacy', 'Kementerian Agama', 'central', 'KANTOR KEMENTERIAN AGAMA KAB KLUNGKUNG 419910', 'Belanja Jasa Lainnya', 'Barang', 'E-Purchasing', 'Bali, Klungkung (Kab.)', 120000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Biaya Tenaga Outsourcing ( 24, OB, @ 5000000 );', 'SPESIFIKASI PEKERJAAN BIAYA TENAGA OUTSOURCING 1. Nama Pekerjaan Penyediaan Tenaga Outsourcing 2. Lingkup Pekerjaan Penyedia menyediakan tenaga kerja outsourcing untuk mendukung kegiatan operasional sesuai kebutuhan instansi, dengan tugas dan tanggung jawab yang ditetapkan dalam kontrak kerja. 3. Jumlah dan Biaya Biaya satuan : Rp5.000.000,- / orang Total biaya : Rp120.000.000,- (periode kerja mengikuti perjanjian/kontrak) 4. Kualifikasi Tenaga Kerja (Minimum) Pendidikan minimal SMA/sederajat Sehat jasmani dan rohani Berpengalaman sebagai OB atau pekerjaan sejenis Disiplin, jujur, dan bertanggung jawab Mampu bekerja secara mandiri maupun tim 5. Ruang Lingkup Tugas Menjaga kebersihan ruangan kerja dan fasilitas kantor Membantu pelayanan operasional kantor Menyiapkan kebutuhan rapat dan kegiatan kantor Tugas lain yang berkaitan dengan operasional sesuai arahan 6. Kewajiban Penyedia Menyediakan tenaga kerja sesuai jumlah dan kualifikasi Mengurus administrasi tenaga kerja (kontrak, gaji, BPJS, dll) Menjamin kedisiplinan dan kinerja tenaga outsourcing Mengganti tenaga kerja apabila tidak memenuhi kinerja 7. Kewajiban Pengguna Memberikan arahan kerja sesuai kebutuhan Menyediakan lingkungan kerja yang aman Melakukan pengawasan terhadap kinerja tenaga outsourcing 8. Hasil Pekerjaan (Output) Tersedianya 24 tenaga OB outsourcing Kelancaran operasional dan kebersihan kantor 9. Metode Pembayaran Pembayaran dilakukan sesuai ketentuan dalam kontrak kerja sama.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1040838);
