INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63617286', 63617286, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN JUNIOR DATA ANALYST PENYUSUNAN ANALISIS DATA PENGEMBANGAN SISTEM INFORMASI LOGBOOK PROYEK PEMBANGUNAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Pengumpulan data dan analisis terhadap data yang ada, khususnya terkait pengembangan Sistem Informasi Logbook Proyek; 2. Focus Group Discussion (FGD) atau konsinyering dengan pihak-pihak terkait; 3. Pengembangan struktur data Sistem Informasi Logbook Proyek; 4. Pendampingan teknis kepada ASN Bappenas dalam proses Penyelenggaraan rapat koordinasi dalam rangka pengembangan dalam rangka pengembangan Sistem Informasi Logbook Proyek; 5. Pendampingan teknis kepada ASN Bappenas dalam proses Pelaksanaan Sosialisasi dan Workshop fasilitasi teknis penggunaan Sistem Informasi Logbook Proyek; 6. Penyusunan laporan kegiatan secara berkala sesuai dengan jadwal dan kegiatan yang telah ditentukan.', '1. Memiliki pendidikan minimal S1 di bidang Ilmu Komputer, Teknik Informatika, Sistem Informasi, Ekonomi, dan/atau Statistika (dibuktikan dengan ijazah jenjang pendidikan); 2. Memiliki pengalaman kerja minimal 2 (dua) tahun di instansi pemerintahan, utamanya terkait pengalokasian sumber dana Non Rupiah Murni (dibuktikan dengan surat referensi/kontrak kerja); 3. Pengalaman kerja minimal 2 (dua) terkait sistem perencanaan dan penganggaran baik berbasis sistem aplikasi maupun non aplikasi (dibuktikan dengan surat referensi/kontrak kerja); 4. Memiliki kemampuan yang baik dalam menganalisis data, merancang, serta membangun basis data Sistem Informasi Perencanaan dan Penganggaran, pengalaman berkoordinasi dengan stakeholders terkait baik Pemerintah Pusat (dibuktikan dengan surat referensi/kontrak kerja/sertifikat).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1042597);
