INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63615155', 63615155, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan BMHP Skrining Hepatitis Tahap II Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 39072090400, 'June 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan BMHP Skrining Hepatitis berupa RDT HBsAg, RDT HBeAg, Katrid HBV DNA Viral Load dan RDT Anti HCV', 'Spesifikasi BMHP Skrining Hepatitis sebagai berikut : 1. RDT HBsAg ; Kegunaan : Untuk deteksi antigen Hepatitis B pada Darah; Stabilitas : Suhu Penyimpanan 2 – 30o C atau sesuai dengan; Metode : Rapid Tes Tanpa Menggunakan Buffer; Kemasan : Maksimal 50 tes/ Kit; Sensitivitas : ≥ 95% (dibuktikan dengan dokumen hasil uji); Spesifitas : ≥ 95% (dibuktikan dengan dokumen hasil uji); Spesimen : Serum, Plasma, dan Whole Blood; Pembacaan Hasil : ≤ 30 menit; Kadaluarsa : Jika Shelf life > 24 bulan maka kedaluwarsa minimal 24 bulan, jika shelf life sama dengan 24 bulan maka kedaluarsa minimal 18 bulan saat diterima di Dinas Kesehatan Provinsi dan atau Gudang Instalasi Farmasi Pusat; Kadaluarsa : Jika Shelf life > 24 bulan maka kedaluwarsa minimal; Izin Edar : Memiliki Izin Edar (NIE) dari Kementerian Kesehatan RI; Kelengkapan : 1. Setiap Box diberi label/ Sticker “Milik Kementerian Kesehatan RI TA 2026, “Tidak diperjualbelikan” 2. Diutamakan Produk TKDN 3. Pejabat pembuat komitmen dapat membulatkan sesuai satuan kemasan produk yang tersedia di pasaran (pembulatan keatas). 2. RDT HBeAg ; Kegunaan Untuk mengetahui replikasi virus hepatitis b dalam milliliter darah untuk menentukan pengobatan selanjutnya; Jenis cassette/Membran/Strip; Sensitivitas ≥98%(dibuktikan dengan dokumen hasil uji); Spesifitas ≥98%(dibuktikan dengan dokumen hasil uji); Spesimen serum/Plasma/wholeblood; Penyimpanan pada suhu 2 – 30o celsius (suhu ruangan); Penyimpanan 2 – 30o C atau sesuai dengan petunjuk yang tertera pada kemasan; Waktu Pembacaan ≤ 30 menit atau sesuai dengan petunjuk penggunaan; Kadaluarsa Jika Shelf life > 24 bulan maka kedaluwarsa minimal 24 bulan, jika shelf life sama dengan 24 bulan maka kedaluarsa minimal 18 bulan saat diterima di Dinas Kesehatan Provinsi dan atau Gudang Instalasi Farmasi Pusat; Izin Edar Memiliki Izin Edar (NIE) Kementerian Kesehatan RI; Keterangan 1. Setiap Box diberi label/ Sticker “Milik Kementerian Kesehatan RI Tahun Anggaran 2026, Tidak diperjualbelikan” 2. Diutamakan Produk TKDN 3. Pejabat pembuat komitmen dapat membulatkan sesuai satuan kemasan produk yang tersedia di pasaran (pembulatan keatas) 3. Katrid HBV DNA Viral Load : Kegunaan Mendeteksi Transkrip DNA dari Virus HBV pada plasma atau serum pasien penderita Hepatitis B; Spesimen Klinis Plasma darah atau serum; Limit Deteksi 10 – 1.000.000.000 IU/mL; Spesimen Klinis Plasma darah atau serum; Sensitifitas Minimal 95%; Spesififisitas 99 -100%; Penyimpanan 2 – 300 C atau sesuai dengan petunjuk yang tertera pada kemasan; Kedaluwarsa Jika Shelf life > 24 bulan maka kedaluwarsa minimal 24 bulan, jika shelf life sama dengan 24 bulan maka kedaluarsa minimal 18 bulan saat diterima di Dinas Kesehatan Provinsi dan atau Gudang Instalasi Farmasi Pusat; Izin Edar Memiliki Izin Edar (NIE) Kementerian Kesehatan RI; Reagen compatible dengan mesin yang sudah ada (Gene Xpert); Keterangan 1. Setiap Box diberi label/ Sticker “Milik Kementerian Kesehatan RI TA 2026, “Tidak diperjualbelikan” 2. Diutamakan Produk TKDN 3. Pejabat pembuat komitmen dapat membulatkan sesuai satuan kemasan produk yang tersedia di pasaran (pembulatan keatas) 4. RDT Anti HCV : Kegunaan Untuk mendeteksi secara dini pada populasi berisiko terhadap Hepatitis C; Metode Rapid Tes tanpa atau dengan buffer individual; Kemasan Maksimal 50 Tes/ Kit; Sensitivitas ≥ 99% (dibuktikan dengan dokumen hasil uji); Spesifitas ≥ 99% (dibuktikan dengan dokumen hasil uji); Spesimen Klinis Whole Blood, plasma, dan serum; Komposisi Recombinan Antigen HCV; Penyimpanan 2 – 300 C atau sesuai dengan petunjuk yang tertera pada kemasan; Pembacaan Hasil ≤ 30 menit atau sesuai dengan petunjuk penggunaan; Kedaluwarsa Jika Shelf life > 24 bulan maka kedaluwarsa minimal 24 bulan, jika shelf life sama dengan 24 bulan maka kedaluarsa minimal 18 bulan saat diterima di Dinas Kesehatan Provinsi dan atau Gudang Instalasi Farmasi Pusat; Keterangan Terdaftar Memiliki Izin Edar (NIE) Kementerian Kesehatan RI Keterangan 1. Setiap Box diberi label/ Sticker “Milik Kementerian Kesehatan RI TA 2026, “Tidak diperjualbelikan” 2. Diutamakan Produk TKDN 3. Pejabat pembuat komitmen dapat membulatkan sesuai satuan kemasan produk yang tersedia di pasaran (pembulatan keatas)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1043102);
