INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63639228', 63639228, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Obat Malaria Tahap II Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 33702976394, 'June 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan Obat Malaria Tahun 2026 Tahap II berupa Dehydro Artemisin 40 mg + Piperaquin 320 mg (DHP), DHP Dispersible (Anak) , Primakuin tab 15 mg, Artesunate Injeksi, Doksisiklin 100 mg, Artemeter Lumefantrin dan Mefloquin 250 mg', 'Spesifikasi Obat Malaria sebagai berikut : 1. Dihydroartemisinin – Piperaquin spesifikasi : a. Deskripsi : FDC (Fixed Dose Combination), masing – masing tablet mengandung 40 mg Dihydroartemisinin(DHA) dan 320 mg Piperaquin tablet. b. Kemasan : 1. Satu blister terdiri dari 9 tablet 2. Informasi tentang obat harus tertera di dalam kemasan dalam bahasa Indonesia. 3. Di luar kemasan harus tertulis kandungan setiap obat 4. Tanggal Produksi 5. Tanggal Kadaluarsa : (masa kadaluarsa minimal 18 bulan terhitung sejak tiba di Instalasi Farmasi Provinsi) 6. No Batch. 7. Mempunyai izin edar dari Badan POM / SAS (Special Acces Scheme) 8. No.Register/SAS 9. Nama Pabrik/Produsen 10. Di luar kemasan harus tertulis kandungan setiap obat; 2. Dihydroartemisinin – Piperaquin Dispersible Tablet spesifikasi : a. Deskripsi : FDC (Fixed Dose Combination), masing – masing tablet mengandung 20 mg Dihydroartemisinin(DHA) dan 160 mg Piperaquin tablet. b. Kemasan : 1. Satu blister terdiri dari 6 tablet 2. Informasi tentang obat harus tertera di dalam kemasan dalam bahasa Indonesia. 3. Di luar kemasan harus tertulis kandungan setiap obat 4. Tanggal Produksi 5. Tanggal Kadaluarsa : (masa kadaluarsa minimal 18 bulan terhitung sejak tiba di Instalasi Farmasi Provinsi) 6. No Batch. 7. Mempunyai izin edar dari Badan POM / SAS (Special Acces Scheme) 8. No.Register/SAS 9. Nama Pabrik/Produsen 10. Di luar kemasan harus tertulis kandungan setiap obat; 3. Artesunat Injeksi Spesifikasi : a. Deskripsi : Derivat artemisinin dalam bentuk bubuk kristal putih b. Kemasan : 1. Dalam kotak berisi satu vial artesunate injeksi yang berisi 60 mg serbuk kering asam artesunate dan pelarut satu ampul (0,6 ml) sodium bikarbonat 5% 2. Tanggal Produksi 3. Tanggal Kadaluarsa : (masa kadaluarsa minimal 18 bulan terhitung sejak tiba di Instalasi Farmasi Provinsi) 4. No.Register 5. No.Batch 6. Nama Pabrik/Produsen 7. Pada kemasan obat tertulis dosis pemakaian sebagai berikut (dalam bahasa Indonesia) :  Untuk malaria berat Dosis : 2.4 mg/kg bb IV (intra vena) pada jam 0, 12, 24 hari pertama dilanjutkan dengan dosis 2.4 mg/kg bb setiap hari sampai pasien sadar  Untuk pra rujukan malaria berat Dosis : 2.4 mg/kg bb IM (intramuscular) 8. Informasi tentang obat harus tertera didalam kemasan dalam bahasa Indonesia. 9. Di luar kemasan harus tertulis kandungan setiap obat. 10. Mempunyai izin edar dari Badan POM; 4. Primakuin tablet spesifikasi: a. Deskripsi : Tiap tablet mengandung 15 mg primakuin b. Kemasan : 1. Tiap kotak berisi 10 blister @10 tablet . 2. Tiap tablet mengandung 15 mg primakuin 3. Scored tablet (silang) tidak mudah hancur tetapi mudah dibelah empat 4. Tanggal produksi 5. Tanggal Kadaluarsa : (masa kadaluarsa minimal 18 bulan terhitung sejak tiba di Instalasi Farmasi Provinsi) 6. No Register 7. No Batch 8. Nama Pabrik / Produsen 9. Di luar kemasan harus tertulis kandungan setiap obat. 10. Informasi tentang obat harus tertera didalam kemasan dalam Bahasa Indonesia. 11. Mempunyai izin edar dari Badan POM; 5. Mefloquine a. Deskripsi : bahan aktif Mefloquine HCl, masa kadaluarsa dari tanggal produksi minimal 18 bulan b. Kemasan : 1. Bahan aktif : Mefloquine HCl 250mg 2. Formulasi : tablet/kaplet/kapsul 3. Beberapa tablet dikemas dalam blister. 4. Pada kemasan dituliskan informasi tentang obat seperti: bahan aktif/kandungan, 5. Brosur atau insert dosis penggunaan, kontraindikasi, reaksi hipersensitifitas (jika ada), dan efek samping. 6. Mencantumkan informasi no Batch, tanggal produksi, dan tanggal kadaluarsa. 7. Mempunyai dan mencantumkan Nomer Ijin Edar (NIE) atau nomer registrasi Special Access Scheme (SAS)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1044892);
